changeSet.sql:
with content as (
  select * from (select unnest(array[0,1,3,5,6]) op) ops, (select unnest(array['${test1.uuid}', '${test2.uuid}']) uuid) uuids
) insert into operationallowed (groupid, metadataid, operationid) (select ${groupid}, metadata.id, content.op from content inner join metadata using (uuid));
